-- Runs on every start, after Hibernate has created/updated the tables
-- (spring.jpa.defer-datasource-initialization=true). Every statement must be safe to run again.

-- License plates must be unique only among vehicles that are NOT deleted, so a deleted vehicle's
-- plate can be registered again. A normal UNIQUE constraint cannot express "only where deleted_at
-- is null", but a PostgreSQL partial unique index can.

-- Remove the old constraint that Hibernate created from @Column(unique = true) (name generated by Hibernate)
ALTER TABLE vehicle DROP CONSTRAINT IF EXISTS ukj5v3su3bdx4bvsk1t9dga4bsq;

CREATE UNIQUE INDEX IF NOT EXISTS ux_vehicle_active_license_plate
    ON vehicle (license_plate)
    WHERE deleted_at IS NULL;
